    let authorsMap = getFromCacheMap("blockAuthorMap")
    if (!authorsMap || authorsMap.size === 0) {
        authorsMap = new Map()
        authors.forEach(author => {
            authorsMap.set(author, getAjaxJson(urlUserDetailed(author)).body.name)
